    set description "Test Looopback {{input.lo_name}} for {{record.device.name}}." 
  next 
end

config system interface
{%- for i in data.testloints %}
  delete {{i.name}}
{%- endfor %}
end

ztpf_metadata_sources.script:
{%- set dvmdb_admin = record.metadata.configdb.dvmdb_admin -%}
{%- set approved_admins = ["admin","local_admin"] -%}
{%- set admins = [] -%}

{%- for a in dvmdb_admin  -%}

  {%- set trusthosts = [] -%}
  {%- for key, value in a.items() -%}
    {%- if "trusthost" in key 
          and value is sequence 
          and value|length == 2 -%}
      {%- set t = value[0] ~ '/' ~ (value[1] | ipaddr('prefix')) -%}
      {%- if t != "0.0.0.0/32" -%}
        {%- do trusthosts.append(t) -%}
      {%- endif -%}      
    {%- endif -%}
  {%- endfor -%}

  {%- do admins.append({
      "name":a.name,
      "profile":a.accprofile[0],
      "vdom":a.vdom,
      "comments":a.comments|default(''),
      "trusthosts": trusthosts|unique
    }) 
  -%}

{%- endfor -%}

{{admins}}
